'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var positive = require( './fixtures/python/positive.json' );
var negative = require( './fixtures/python/negative.json' );


// VARIABLES //

var expitf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( expitf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof expitf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` when provided `NaN`', opts, function test( t ) {
	var y = expitf( NaN );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.5` when provided `0`', opts, function test( t ) {
	var y = expitf( 0.0 );
	t.strictEqual( y, 0.5, 'returns 0.5' );
	t.end();
});

tape( 'the function returns `1.0` when provided `+Infinity`', opts, function test( t ) {
	var y = expitf( PINF );
	t.strictEqual( y, 1.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` when provided `-Infinity`', opts, function test( t ) {
	var y = expitf( NINF );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the standard logistic function for negative numbers', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = negative.expected;
	x = negative.x;

	for ( i = 0; i < x.length; i++ ) {
		y = expitf( x[ i ] );
		e = float64ToFloat32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the standard logistic function for positive numbers', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = positive.expected;
	x = positive.x;

	for ( i = 0; i < x.length; i++ ) {
		y = expitf( x[ i ] );
		e = float64ToFloat32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});
